require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';Auth::requireRole('admin');$counts=['donors'=>(int)db()->query("SELECT COUNT(*) FROM users WHERE role='donor'")->fetchColumn(),'eligible'=>(int)db()->query("SELECT COUNT(*) FROM donor_profiles WHERE eligibility_status='eligible'")->fetchColumn(),'hospitals'=>(int)db()->query("SELECT COUNT(*) FROM hospitals WHERE status='active'")->fetchColumn(),'open'=>(int)db()->query("SELECT COUNT(*) FROM emergency_requests WHERE status='open'")->fetchColumn(),'security'=>(int)db()->query("SELECT COUNT(*) FROM security_events WHERE severity IN ('warning','high') AND created_at>=DATE_SUB(NOW(),INTERVAL 7 DAY)")->fetchColumn()];$recent=db()->query("SELECT e.*,h.name hospital_name FROM emergency_requests e JOIN hospitals h ON h.id=e.hospital_id ORDER BY e.created_at DESC LIMIT 10")->fetchAll();$pageTitle='Admin Dashboard';require dirname(dirname(__DIR__)).'/src/templates/header.php';?>
<section class="dashboard"><div class="container"><div class="dash-head"><div><div class="eyebrow">Administration</div><h1>System overview</h1><p class="page-note">Manage access, monitor activity and maintain prototype configuration.</p></div></div><?=admin_nav()?><div class="metrics"><div class="metric"><span>Donor accounts</span><strong><?=e((string)$counts['donors'])?></strong></div><div class="metric"><span>Eligible donors</span><strong><?=e((string)$counts['eligible'])?></strong></div><div class="metric"><span>Active hospitals</span><strong><?=e((string)$counts['hospitals'])?></strong></div><div class="metric"><span>Open emergencies</span><strong><?=e((string)$counts['open'])?></strong></div></div><?php if($counts['security']>0):?><div class="info-note"><strong>Security review:</strong> <?=e((string)$counts['security'])?> warning/high event(s) were recorded in the last 7 days. <a href="<?=e(url('admin/security.php'))?>">Review events</a>.</div><?php endif;?><h2>Recent emergencies</h2><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Hospital</th><th>Blood</th><th>District</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$recent):?><tr><td colspan="6" class="empty">No requests yet.</td></tr><?php endif;?><?php foreach($recent as $r):?><tr><td>#<?=e((string)$r['id'])?></td><td><?=e($r['hospital_name'])?></td><td><?=e($r['blood_group'])?></td><td><?=e($r['district'])?></td><td><span class="badge <?=$r['status']==='fulfilled'?'green':($r['status']==='open'?'amber':'gray')?>"><?=e($r['status'])?></span></td><td><a href="<?=e(url('hospital/emergency-view.php?id='.(int)$r['id']))?>">Open</a></td></tr><?php endforeach;?></tbody></table></div></div></section>
